CREATE TABLE IF NOT EXISTS "DailyQuote" (
    "id" TEXT NOT NULL,
    "text" TEXT NOT NULL,
    "author" TEXT NOT NULL,
    "source" TEXT NOT NULL,
    "translator" TEXT NOT NULL DEFAULT '',
    "sortOrder" INTEGER NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "DailyQuote_pkey" PRIMARY KEY ("id")
);

CREATE INDEX IF NOT EXISTS "DailyQuote_sortOrder_idx" ON "DailyQuote" ("sortOrder");

ALTER TABLE "DailyQuote" ALTER COLUMN "createdAt" SET DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE "DailyQuote" ALTER COLUMN "updatedAt" SET DEFAULT CURRENT_TIMESTAMP;

ON CONFLICT ("id") DO NOTHING;
